'use strict';
(()=>{class VoiceRoom{
 constructor(send,notice){this.send=send;this.notice=notice;this.peers=new Map();this.muted=true;this.stream=null;this.identity='';this.roster=[];this.levels=[];this.epoch=0;}
 async join(code,id){if(this.stream)return;const epoch=++this.epoch;let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});if(epoch!==this.epoch){stream.getTracks().forEach(t=>t.stop());return;}this.stream=stream;this.identity=id;this.muted=true;stream.getAudioTracks().forEach(t=>t.enabled=false);let config;if(window.PK_CONFIG?.preview){const r=await fetch(`/api/pk/${code}/ice`,{credentials:'same-origin'});if(!r.ok)throw Error('Chưa lấy được cấu hình cuộc gọi.');config=await r.json();}else config=await window.KienCloud.api('/pk/'+code+'/ice',undefined,true);if(epoch!==this.epoch){stream.getTracks().forEach(t=>t.stop());return;}this.ice=Array.isArray(config.iceServers)?config.iceServers:[config.iceServers];this.relay=config.relay;this.context=new AudioContext();this.watchLevel(stream,id);this.send({type:'voice',joined:true,muted:true});this.notice(config.relay?'Đã vào voice. Micro đang tắt.':'Đã vào voice, micro đang tắt. Bản thử đang dùng kết nối trực tiếp; mạng hạn chế có thể cần TURN.');this.sync(this.roster);}catch(error){if(epoch!==this.epoch){stream?.getTracks().forEach(t=>t.stop());return;}await this.leave();this.notice(error.name==='NotAllowedError'?'Bạn chưa cho phép micro. Chat và quiz vẫn dùng bình thường.':error.message||'Chưa mở được micro.');}}
 sync(players){this.roster=players;if(!this.stream)return;const ids=players.filter(p=>p.id!==this.identity&&p.voice&&p.online&&!p.left).map(p=>p.id);for(const[id,peer]of this.peers)if(!ids.includes(id)){peer.pc.close();peer.audio?.remove();this.levels=this.levels.filter(item=>{if(item.id!==id)return true;item.source.disconnect();return false;});this.peers.delete(id);}for(const id of ids)this.ensure(id);}
 ensure(id){if(this.peers.has(id))return this.peers.get(id);const pc=new RTCPeerConnection({iceServers:this.ice||[]}),entry={pc,candidates:[],making:false,ignore:false};this.peers.set(id,entry);this.stream.getTracks().forEach(track=>pc.addTrack(track,this.stream));pc.onicecandidate=e=>{if(e.candidate)this.send({type:'signal',target:id,payload:{candidate:e.candidate.toJSON()}});};pc.ontrack=e=>{if(this.peers.get(id)!==entry||!this.stream)return;let audio=entry.audio;if(!audio){audio=document.createElement('audio');audio.autoplay=true;audio.setAttribute('playsinline','');audio.dataset.pkAudio=id;document.body.append(audio);entry.audio=audio;}const stream=e.streams[0]||new MediaStream([e.track]);audio.srcObject=stream;audio.play().catch(()=>this.notice('Trình duyệt chặn phát âm thanh. Bấm “Nghe âm thanh” trong voice.'));this.watchLevel(stream,id);};pc.onconnectionstatechange=()=>{if(pc.connectionState==='failed')this.notice('Voice chưa kết nối được với một thành viên. Thử vào lại; hai mạng khác nhau có thể cần TURN.');};pc.onnegotiationneeded=async()=>{if(this.identity>id)return;try{entry.making=true;await pc.setLocalDescription(await pc.createOffer());this.send({type:'signal',target:id,payload:{description:pc.localDescription.toJSON()}});}catch{this.notice('Chưa thương lượng được âm thanh. Thử rời và vào lại voice.');}finally{entry.making=false;}};return entry;}
 async signal(id,payload){if(!this.stream)return;try{const entry=this.ensure(id),pc=entry.pc;if(payload.description){const d=payload.description,collision=d.type==='offer'&&(entry.making||pc.signalingState!=='stable');entry.ignore=this.identity<id&&collision;if(entry.ignore)return;if(collision)await pc.setLocalDescription({type:'rollback'});await pc.setRemoteDescription(d);for(const c of entry.candidates.splice(0))await pc.addIceCandidate(c);if(d.type==='offer'){await pc.setLocalDescription(await pc.createAnswer());this.send({type:'signal',target:id,payload:{description:pc.localDescription.toJSON()}});}}else if(payload.candidate){if(pc.remoteDescription)await pc.addIceCandidate(payload.candidate);else entry.candidates.push(payload.candidate);}}catch{this.notice('Một kết nối voice bị gián đoạn. Hãy vào lại voice nếu không nghe được.');}}
 toggle(){if(!this.stream)return;this.muted=!this.muted;this.stream.getAudioTracks().forEach(t=>t.enabled=!this.muted);this.send({type:'voice',joined:true,muted:this.muted});}
 listen(){this.context?.resume();for(const p of this.peers.values())p.audio?.play().catch(()=>{});}
 watchLevel(stream,id){try{const analyser=this.context.createAnalyser();analyser.fftSize=256;const source=this.context.createMediaStreamSource(stream);source.connect(analyser);this.levels.push({id,analyser,source,data:new Uint8Array(256)});if(!this.meter)this.meter=setInterval(()=>{if(document.hidden)return;for(const item of this.levels){item.analyser.getByteTimeDomainData(item.data);const level=Math.sqrt(item.data.reduce((n,v)=>n+(v-128)**2,0)/item.data.length);for(const el of document.querySelectorAll('[data-pk-peer]'))if(el.dataset.pkPeer===item.id)el.classList.toggle('pk-speaking',level>4);}},150);}catch{}}
 async leave(){this.epoch++;if(this.stream)this.send({type:'voice',joined:false,muted:true});this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;for(const p of this.peers.values()){p.pc.close();p.audio?.remove();}this.peers.clear();clearInterval(this.meter);this.meter=0;this.levels.forEach(x=>x.source.disconnect());this.levels=[];const context=this.context;this.context=null;await context?.close().catch(()=>{});}
}window.KienBattleVoice=VoiceRoom;})();
